.message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #3a3a3a;
    background: #2b2b2b;
    align-items: flex-end;
}

.message-input textarea {
    flex: 1;
    resize: none;
    border: 1px solid #444;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.9rem;
    background: #1e1e1e;
    color: #e0e0e0;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-input textarea:focus {
    border-color: #5b8def;
}

.send-btn {
    padding: 8px 18px;
    background-color: #5b8def;
    color: #fff;
    border: none;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background-color 0.15s;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background-color: #4a7de0;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

