@page "/chat"
@layout sv_58bfa8905c02475e82b1f62dd3967037.Components.Layout.ChatLayout
@rendermode InteractiveServer
@using sv_58bfa8905c02475e82b1f62dd3967037.Services
@using sv_58bfa8905c02475e82b1f62dd3967037.Components.Chat
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-container">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_selectedChannel?.Id ?? 0"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="chat-main @(_threadOpen ? "" : "expanded")">
        <MessageArea SelectedChannel="_selectedChannel"
                     Messages="_messages"
                     ThreadSummaries="_threadSummaries"
                     HasMoreMessages="_hasMoreMessages"
                     IsLoadingMore="_isLoadingMore"
                     OnSendMessage="SendMessage"
                     OnOpenThread="OpenThread"
                     OnReact="AddReaction"
                     OnLoadMore="LoadMoreMessages" />
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         Replies="_threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply"
                         OnReact="AddReaction" />
        </div>
    }
</div>

@code {
    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, ThreadSummary> _threadSummaries = [];
    private bool _hasMoreMessages;
    private bool _isLoadingMore;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = [];

    private const int PageSize = 30;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _selectedChannel = channel;
        _messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _hasMoreMessages = _messages.Count >= PageSize;
        _threadSummaries = BuildThreadSummaries(_messages);

        CloseThread();
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to update unread counts
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (_selectedChannel is null || _isLoadingMore) return;

        _isLoadingMore = true;
        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messages.Count, PageSize);
        _hasMoreMessages = older.Count >= PageSize;
        _messages.InsertRange(0, older);
        _threadSummaries = BuildThreadSummaries(_messages);
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;

        var message = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(message);
    }

    private async Task OpenThread(int rootMessageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(rootMessageId);
        _threadOpen = true;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootMessage = null;
        _threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_selectedChannel is null || _threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);

        // Update thread summary in main view
        if (_threadSummaries.ContainsKey(_threadRootMessage.Id))
        {
            var existing = _threadSummaries[_threadRootMessage.Id];
            _threadSummaries[_threadRootMessage.Id] = existing with
            {
                ReplyCount = existing.ReplyCount + 1,
                LastReplyAt = reply.SentAt
            };
        }
        else
        {
            _threadSummaries[_threadRootMessage.Id] = new ThreadSummary(_threadRootMessage.Id, 1, reply.SentAt);
        }
    }

    private async Task AddReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh messages to show updated reactions
        if (_selectedChannel is not null)
        {
            _messages = await ChatService.GetMessagesAsync(_selectedChannel.Id, 0, _messages.Count);
        }

        if (_threadOpen && _threadRootMessage is not null)
        {
            _threadReplies = await ChatService.GetThreadAsync(_threadRootMessage.Id);
        }
    }

    private static Dictionary<int, ThreadSummary> BuildThreadSummaries(List<Message> messages)
    {
        var summaries = new Dictionary<int, ThreadSummary>();
        var replies = messages.Where(m => m.ReplyToId.HasValue).ToList();

        foreach (var group in replies.GroupBy(m => m.ReplyToId!.Value))
        {
            summaries[group.Key] = new ThreadSummary(
                group.Key,
                group.Count(),
                group.Max(m => m.SentAt)
            );
        }

        return summaries;
    }
}

